import {mountExperiment} from './experiment-ui.js';
import {R,C,T,B,fmt,stats,note,node,flow,table,colors,legend,strip,bars,timeline,plot} from './computer-ui.js';
import {integer8,pipeline,branches,parallelTime,matrixAccess,cacheTrace,sharing,roofline,schedule,translation,memoryBudget,raceStep,lockStep,batchCost,eventLoop,tcpThroughput,percentile,latencySample,benchmark} from './computer-models.js';
const labs={};

labs.bits=()=>({title:'Interpret one byte',state:{value:127,add:1},controls:[R('value','Starting byte',0,255),R('add','Add',0,32)],render:s=>{
  const r=integer8(s.value,s.add);
  return `<div class="cs-bits" role="img" aria-label="Result bits ${r.bits}">${[...r.bits].map((bit,i)=>`<div class="${bit==='1'?'on':''}"><small>bit ${7-i}</small><strong>${bit}</strong><span>${i===0?'sign / 128':2**(7-i)}</span></div>`).join('')}</div>`+stats(['Unsigned result',r.unsigned],['Signed interpretation',r.signed],['Carry out',r.carry?'1 · discarded':'0'])+note(`${s.value} + ${s.add} = ${s.value+s.add}; store the low 8 bits. ${r.unsigned>=128?'The same stored byte has a negative signed interpretation.':'The high bit is zero, so both interpretations agree.'}`);
},foot:'Explicit modulo-256 byte arithmetic. Language-level signed overflow may have different rules.'});

labs.pipeline=()=>({title:'Fill the execution slots',state:{chains:1,width:2,latency:3,tick:0},controls:[R('chains','Independent chains',1,6),R('width','Issue slots / cycle',1,4),R('latency','Result latency (cycles)',1,6),B('step','Step one cycle'),B('finish','Show completion')],onChange:s=>{s.tick=0;},actions:{step:s=>{s.tick=Math.min(pipeline(s.chains,s.width,s.latency).cycles,s.tick+1);},finish:s=>{s.tick=pipeline(s.chains,s.width,s.latency).cycles;}},render:s=>{
  const r=pipeline(s.chains,s.width,s.latency),done=r.instructions.filter(i=>i.end<=s.tick).length;
  return `<div class="cs-schedule-scroll"><div class="cs-pipeline">${r.instructions.map(i=>`<div class="cs-time-row ${i.end<=s.tick?'cs-done':''}"><span>I${i.id+1} · chain ${i.chain+1}</span><div class="cs-time-track"><i style="left:${i.start/r.cycles*100}%;width:${(i.end-i.start)/r.cycles*100}%;background:${colors[i.chain]};opacity:${i.start<s.tick?1:.2}"></i><em style="left:${s.tick/r.cycles*100}%"></em></div><small>${i.start}–${i.end}</small></div>`).join('')}</div></div>`+stats(['At cycle',`${s.tick} / ${r.cycles}`],['Completed',`${done} / 12`],['Full-run instructions / cycle',fmt(12/r.cycles,2)])+note('Dim bars are scheduled work; bright bars have started. Add independent chains, then step again. Wider issue only helps when operands are ready.');
},foot:'12 ordered instructions, equal latency, fully pipelined units, no cache misses. Colors identify dependency chains; bars show start–completion cycles.'});

labs.branches=()=>({title:'Train a tiny branch predictor',state:{pattern:'Alternating',n:0,penalty:10},controls:[C('pattern','Outcome pattern',['Steady','Alternating','Clustered','Irregular']),R('penalty','Miss penalty (cycles)',2,20),B('step','Resolve next branch'),B('finish','Resolve all 24')],onChange:(s,key)=>{if(key==='pattern')s.n=0;},actions:{step:s=>{s.n=Math.min(24,s.n+1);},finish:s=>{s.n=24;}},render:s=>{
  const trace=branches(s.pattern),seen=trace.slice(0,s.n),miss=seen.filter(x=>x.miss).length,counter=s.n?seen.at(-1).after:1;
  return `<div class="cs-predictor">${['Strong N','Weak N','Weak T','Strong T'].map((label,i)=>`<div class="${counter===i?'active':''}"><small>${i.toString(2).padStart(2,'0')}</small><b>${label}</b></div>`).join('')}</div><div class="cs-outcomes">${trace.map((b,i)=>`<span class="${i>=s.n?'pending':b.miss?'miss':'hit'}" title="Branch ${i+1}: predicted ${b.prediction?'taken':'not taken'}, actual ${b.actual?'taken':'not taken'}">${i>=s.n?'·':b.actual?'T':'N'}<small>${i>=s.n?'?':b.miss?'miss':'hit'}</small></span>`).join('')}</div>`+stats(['Resolved',`${s.n} / 24`],['Mispredictions',miss],['Toy total cycles',s.n+miss*s.penalty])+note('T = taken; N = not taken. Predictor starts weakly not-taken. Its state changes only after each outcome resolves.');
},foot:'One two-bit saturating counter, one cycle per branch plus a chosen miss penalty. Modern history-based predictors behave differently.'});

labs.parallel=()=>({title:'Find the useful worker count',state:{p:80,n:4,overhead:1},controls:[R('p','Parallel work (%)',0,100,5),R('n','Workers',1,32),R('overhead','Cost per extra worker (ms)',0,5,.25)],render:s=>{
  const r=parallelTime(s.p/100,s.n,s.overhead),points=Array.from({length:32},(_,i)=>parallelTime(s.p/100,i+1,s.overhead).speedup),max=Math.max(2,...points),x=n=>55+(n-1)/31*550,y=v=>210-v/max*180;
  return plot(`<polyline points="${points.map((v,i)=>`${x(i+1)},${y(v)}`).join(' ')}" fill="none" stroke="${colors[0]}" stroke-width="3"/><circle cx="${x(s.n)}" cy="${y(r.speedup)}" r="6" fill="${colors[1]}"/><text x="65" y="35">Speedup · top ${fmt(max)}×</text><text x="55" y="238">1 worker</text><text x="520" y="238">32 workers</text>`,`Speedup ${fmt(r.speedup)} at ${s.n} workers`)+strip([['Serial ms',r.serial,colors[2]],['Parallel ms',r.parallel,colors[1]],['Coordination ms',r.coordination,colors[0]]])+stats(['Runtime',`${fmt(r.total)} ms`],['Speedup',`${fmt(r.speedup,2)}×`],['Best count in this model',points.indexOf(Math.max(...points))+1]);
},foot:'Fixed 100 ms baseline. Perfect division of parallel work plus linear coordination cost. No bandwidth or scheduling limits.'});

labs.cache=()=>({title:'Walk a row-major matrix',state:{order:'Columns',capacity:4,n:8},controls:[C('order','Traversal',['Rows','Columns','Tiled']),R('capacity','Cache lines',2,16),B('step','Read next value'),B('finish','Finish traversal')],onChange:s=>{s.n=0;},actions:{step:s=>{s.n=Math.min(64,s.n+1);},finish:s=>{s.n=64;}},render:s=>{
  const trace=cacheTrace(matrixAccess(s.order),s.capacity).slice(0,s.n),last=trace.at(-1),hits=trace.filter(x=>x.hit).length,seen=new Map(trace.map(x=>[x.address,x]));
  return `<div class="cs-cache-layout"><div><p class="small">8 × 8 matrix · four values per line</p><div class="cs-matrix" role="img" aria-label="${s.n} values visited; ${hits} hits and ${s.n-hits} misses">${Array.from({length:64},(_,i)=>`<span class="${seen.has(i)?seen.get(i).hit?'hit':'miss':''} ${last?.address===i?'current':''}" title="Address ${i}, line ${Math.floor(i/4)}${seen.has(i)?seen.get(i).hit?', hit':', miss':''}">${i}</span>`).join('')}</div></div><div><p class="small">Cache · LRU → most recent</p><div class="cs-cache-slots">${Array.from({length:s.capacity},(_,i)=>`<div>${last?.cache[i]!==undefined?`L${last.cache[i]} <small>values ${last.cache[i]*4}–${last.cache[i]*4+3}</small>`:'<span class="muted">empty</span>'}</div>`).join('')}</div></div></div>`+legend([['Hit',colors[1]],['Miss',colors[0]]])+stats(['Accesses',s.n],['Cache misses',s.n-hits],['Hit rate',s.n?`${fmt(hits/s.n*100)}%`:'—'])+note(last?`Read value ${last.address} from line ${last.line}: ${last.hit?'hit':`miss${last.evicted!==null?`, evicted line ${last.evicted}`:''}`}.`:'Read a value to begin. Tiled traversal visits 4 × 4 tiles, column-first within each tile.');
},foot:'Cold, fully associative LRU cache; four values per line. No prefetching, overlapping misses, or set conflicts.'});

labs.sharing=()=>({title:'Watch cache-line ownership move',state:{padded:false,writes:0},controls:[T('padded','Place counters on separate lines'),B('step','Next alternating write'),B('finish','Run 16 writes')],onChange:s=>{s.writes=0;},actions:{step:s=>{s.writes=Math.min(32,s.writes+1);},finish:s=>{s.writes=16;}},render:s=>{
  const r=sharing(s.padded,s.writes),last=r.trace.at(-1);
  return flow([['Core 0',`counter A = ${Math.ceil(s.writes/2)}`],['Coherence traffic',`${r.transfers} transfers`,'purple'],['Core 1',`counter B = ${Math.floor(s.writes/2)}`,'blue']])+`<div class="cs-cache-lines">${(s.padded?['A + padding','B + padding']:['A | B | unused bytes']).map((label,i)=>`<div><small>64-byte line ${i}</small><strong>${label}</strong><span>${s.padded?(r.trace.some(t=>t.core===i)?`owned by core ${i}`:'not yet owned'):last?`owned by core ${last.core}`:'not yet owned'}</span></div>`).join('')}</div>`+stats(['Writes',s.writes],['Ownership transfers',r.transfers],['Reserved line space',`${r.bytes} B`])+note(s.padded?'The two hot writers no longer compete for one line. The footprint doubles in this deliberately small layout.':'Alternate writers. Each needs exclusive ownership even though the counters are distinct variables.');
},foot:'Two single-writer counters; 64-byte lines and strict alternating writes. Counts ownership transfers, not cycles or full MESI states.'});

labs.roofline=()=>({title:'Find the limiting roof',state:{intensity:2,bandwidth:50,peak:800},controls:[R('intensity','Arithmetic intensity (FLOP/byte)',.5,32,.5),R('bandwidth','Memory bandwidth (GB/s)',25,200,25),R('peak','Peak compute (GFLOP/s)',200,2000,100)],render:s=>{
  const r=roofline(s.intensity,s.bandwidth,s.peak),x=v=>55+v/32*550,y=v=>210-v/2000*180;
  const pts=Array.from({length:65},(_,i)=>`${x(i/2)},${y(roofline(i/2,s.bandwidth,s.peak).attainable)}`).join(' ');
  return plot(`<polyline points="${pts}" fill="none" stroke="${colors[0]}" stroke-width="3"/><line x1="55" x2="605" y1="${y(s.peak)}" y2="${y(s.peak)}" stroke="${colors[2]}" stroke-dasharray="4 4"/><circle cx="${x(s.intensity)}" cy="${y(r.attainable)}" r="7" fill="${colors[1]}"/><text x="65" y="35">0–2,000 GFLOP/s</text><text x="55" y="238">0 FLOP/byte</text><text x="505" y="238">32 FLOP/byte</text>`,`${r.bound} limited to ${r.attainable} GFLOP/s`)+stats(['Attainable ceiling',`${fmt(r.attainable)} GFLOP/s`],['Limiting resource',r.bound],['Ridge intensity',`${fmt(r.ridge)} FLOP/B`])+note('Move the blue point by increasing useful work per transferred byte. Raising the dashed compute roof only helps points already constrained by it.');
},foot:'Linear axes; ideal bandwidth/compute upper bound with decimal units. Real performance can fall below both roofs.'});

labs.allocation=()=>({title:'Keep references, keep memory',state:{retained:25,live:0,garbage:0,allocated:0,collections:0},controls:[R('retained','Retained from each new batch (%)',0,100,5),B('allocate','Allocate 40 MiB'),B('collect','Collect garbage'),B('release','Drop retained references')],actions:{allocate:s=>{s.allocated+=40;s.live+=40*s.retained/100;s.garbage+=40*(1-s.retained/100);},collect:s=>{s.garbage=0;s.collections++;},release:s=>{s.garbage+=s.live;s.live=0;}},render:s=>{
  return flow([['Roots / references',`${fmt(s.live)} MiB reachable`],['Unreachable objects',`${fmt(s.garbage)} MiB collectible`,'purple'],['Collector',`${s.collections} runs`,'blue']])+strip([['Live MiB',s.live,colors[1]],['Garbage MiB',s.garbage,colors[0]]],'Heap occupancy')+stats(['Current toy heap',`${fmt(s.live+s.garbage)} MiB`],['Total allocated over time',`${fmt(s.allocated)} MiB`],['Reclaimable now',`${fmt(s.garbage)} MiB`])+note('Allocate several batches, then collect. Drop retained references and collect again. Changing the slider affects future allocations only.');
},foot:'Explicit whole-heap collection with no runtime metadata, fragmentation, automatic triggers, or return-to-OS delay.'});

labs.processes=()=>({title:'Same address, different ownership',state:{kind:'Separate processes',a:0,b:0},controls:[C('kind','Execution contexts',['Separate processes','Threads in one process']),B('writeA','A increments its value'),B('writeB','B increments its value')],onChange:s=>{s.a=0;s.b=0;},actions:{writeA:s=>{s.a++;},writeB:s=>{if(s.kind==='Separate processes')s.b++;else s.a++;}},render:s=>{
  const shared=s.kind==='Threads in one process';
  return `<div class="cs-address-spaces ${shared?'shared':''}"><div>${node('Context A',`0x1000 → ${s.a}`)}<small>registers · stack A</small></div><div class="cs-address-boundary">${shared?'One shared address space':'Two isolated address spaces'}</div><div>${node('Context B',`0x1000 → ${shared?s.a:s.b}`,'blue')}<small>registers · stack B</small></div></div>`+flow(shared?[['Mapping','shared physical storage'],['Write visibility','A and B see the same value','blue']]:[['A mapping','physical frame 6'],['B mapping','physical frame 2','blue']])+note(shared?'Both contexts can access the shared location. These button actions execute sequentially; concurrent updates need synchronization.':'An identical virtual address does not imply shared memory. A write in one process leaves the other process’s value unchanged.');
},foot:'Conceptual mappings; separate processes have no explicit shared-memory mapping. Not a fork/copy-on-write simulation.'});

labs.scheduling=()=>({title:'Schedule three ready jobs',state:{policy:'FIFO',quantum:3,cost:1},controls:[C('policy','Policy',['FIFO','Shortest first','Round robin']),R('quantum','Round-robin quantum (ms)',1,6),R('cost','Context-switch cost (ms)',0,2,.25)],render:s=>{
  const r=schedule(s.policy,s.quantum,s.cost);
  return `<div class="cs-schedule-scroll"><div class="cs-gantt">${r.segments.map(seg=>`<div style="flex:${seg.duration};background:${seg.job==='switch'?'#566061':colors[seg.job]}" title="${seg.job==='switch'?'Context switch':'Job '+String.fromCharCode(65+seg.job)}: ${seg.start}–${seg.start+seg.duration} ms">${seg.job!=='switch'&&seg.duration>=2?String.fromCharCode(65+seg.job):''}</div>`).join('')}</div></div>`+legend([['A · 12 ms',colors[0]],['B · 3 ms',colors[1]],['C · 3 ms',colors[2]],['Switch', '#566061']])+table(['Job','First response','Completion'],r.starts.map((t,i)=>[String.fromCharCode(65+i),`${fmt(t)} ms`,`${fmt(r.ends[i])} ms`]))+stats(['Total elapsed',`${fmt(r.time)} ms`],['Switch overhead',`${fmt(r.overhead)} ms`],['Mean completion',`${fmt(r.ends.reduce((a,b)=>a+b,0)/3)} ms`]);
},foot:'One core; all jobs ready at t=0; known CPU-only durations; switching charged only between distinct jobs. Modern OS policies differ.'});

labs.translation=()=>({title:'Translate a virtual address',state:{address:5000,tlb:false,page:'Resident'},controls:[R('address','Virtual byte address',0,16383),T('tlb','TLB hit if page is resident'),C('page','Page state',['Resident','Demand zero','On storage','Invalid'])],render:s=>{
  const r=translation(s.address),resident=s.page==='Resident',hit=s.tlb&&resident;
  return `<div class="cs-address"><span>Virtual page <b>${r.vpn}</b></span><span>12-bit offset <b>${r.offset}</b></span></div>`+flow([['Virtual address',s.address],['TLB',hit?'hit':'miss','blue'],['Page table',resident?`frame ${r.frame}`:s.page,'purple'],['Result',resident?`physical ${r.physical}`:s.page==='Invalid'?'access rejected':'OS handles fault']])+stats(['Page size','4,096 B'],['Page fault',resident?'No':'Yes'],['Storage read required',s.page==='On storage'?'Yes':'No'])+note(hit?'The cached mapping supplies the physical frame; the byte offset is preserved.':resident?'A page-table walk resolves the TLB miss. The actual data is already in RAM.':s.page==='Demand zero'?'The OS can supply a zero-filled page without reading data from storage.':s.page==='On storage'?'This valid mapping needs its data loaded from backing storage before retrying.':'No valid mapping permits this access. The process receives a fault; a stale TLB mapping is not permitted.',s.page==='Invalid');
},foot:'Four virtual pages, 4 KiB each; illustrative physical frames. TLB entries apply only to resident valid pages; permissions and multi-level walks are omitted.'});

labs.limits=()=>({title:'Fit the whole memory budget',state:{heap:384,native:128,cache:128,limit:512},controls:[R('heap','Live heap (MiB)',64,768,32),R('native','Native + stacks (MiB)',32,256,32),R('cache','Clean file cache (MiB)',0,256,32),R('limit','Container limit (MiB)',256,1024,64)],render:s=>{
  const r=memoryBudget(s.heap,s.native,s.cache,s.limit);
  return strip([['Heap MiB',s.heap,colors[1]],['Native MiB',s.native,colors[2]],['Cache MiB',s.cache,colors[0]]])+bars([['Before reclaim',r.total],['After reclaim',r.after,colors[1]],['Limit',s.limit,colors[2]]])+stats(['Reclaimable cache used',`${r.reclaim} MiB`],['Remaining excess',`${r.excess} MiB`],['Fits after reclaim',r.excess?'No':'Yes'])+note(r.excess?'The remaining live/native budget exceeds the limit. This model has no swap or further reclaim; allocating this demand cannot succeed.':r.reclaim?'The budget fits only after reclaiming clean file cache. Less cache can increase future I/O.':'This demand fits inside the chosen limit. Leave headroom for bursts and unmodeled charged memory.',!!r.excess);
},foot:'Budget arithmetic; all file cache is clean/reclaimable, heap/native are unreclaimable, no swap. Real cgroup accounting and OOM selection are more complex.'});

labs.race=()=>({title:'Schedule the lost update yourself',state:{atomic:false,value:0,pc:{A:0,B:0},local:{A:null,B:null},log:[]},controls:[T('atomic','Use atomic read-modify-write'),B('a','Step thread A'),B('b','Step thread B')],onChange:s=>{s.value=0;s.pc={A:0,B:0};s.local={A:null,B:null};s.log=[];},actions:{a:s=>Object.assign(s,raceStep(s,'A',s.atomic)),b:s=>Object.assign(s,raceStep(s,'B',s.atomic))},render:s=>{
  const done=s.pc.A===2&&s.pc.B===2;
  return flow([['Thread A',s.pc.A===2?'done':s.pc.A===1?`local ${s.local.A} → write ${s.local.A+1}`:'next: read / increment'],['Shared counter',s.value,'purple'],['Thread B',s.pc.B===2?'done':s.pc.B===1?`local ${s.local.B} → write ${s.local.B+1}`:'next: read / increment','blue']])+`<ol class="cs-event-log">${s.log.length?s.log.map(x=>`<li>${x}</li>`).join(''):'<li>Try A → B → A → B.</li>'}</ol>`+note(done?s.value===2?'Both increments are present. Reset and try a different interleaving.':'Both threads finished, but one update was overwritten. Enable atomic read-modify-write and replay the same schedule.':'The next step is your choice. Each thread must finish once; the expected final value is 2.',done&&s.value!==2);
},foot:'Defined toy read/write steps. A real data race may be undefined in languages such as C++; this is not a hardware memory-model simulator.'});

labs.deadlock=()=>({title:'Create, then prevent, circular wait',state:{ordered:false,pc:{A:0,B:0},owners:{X:null,Y:null}},controls:[T('ordered','Both acquire X before Y'),B('a','Step thread A'),B('b','Step thread B')],onChange:s=>{s.pc={A:0,B:0};s.owners={X:null,Y:null};},actions:{a:s=>Object.assign(s,lockStep(s,'A',s.ordered)),b:s=>Object.assign(s,lockStep(s,'B',s.ordered))},render:s=>{
  const next=t=>s.pc[t]===3?'finished':s.pc[t]===2?'release both':`acquire ${(t==='A'||s.ordered?['X','Y']:['Y','X'])[s.pc[t]]}`;
  const dead=!s.ordered&&s.pc.A===1&&s.pc.B===1;
  return `<div class="cs-lock-map ${dead?'blocked':''}">${node('Thread A',next('A'))}${node('Lock X',s.owners.X?`owned by ${s.owners.X}`:'free','purple')}${node('Thread B',next('B'),'blue')}${node('Lock Y',s.owners.Y?`owned by ${s.owners.Y}`:'free','purple')}</div>`+flow([['A needs',next('A')],['Wait graph',dead?'A → B → A':'no cycle','purple'],['B needs',next('B'),'blue']])+note(dead?'Deadlock: A cannot release X until it gets Y; B cannot release Y until it gets X. Extra step clicks cannot break the cycle. Reset or enable common ordering.':'Acquire two locks, then step once more to release. A blocked acquisition leaves that thread’s state unchanged.',dead);
},foot:'Two non-reentrant mutexes; no timeout or forced lock release. Common ordering prevents this specific acquisition cycle.'});

labs.publication=()=>({title:'Publish a payload with a ready flag',state:{mode:'Relaxed atomics',early:false,phase:0},controls:[C('mode','Flag ordering',['Relaxed atomics','Release / acquire']),T('early','Payload already visible to reader'),B('step','Next writer step')],onChange:(s,key)=>{if(key==='mode')s.phase=0;},actions:{step:s=>{s.phase=Math.min(2,s.phase+1);}},render:s=>{
  const ready=s.phase===2,visible=s.phase>0&&(s.early||ready&&s.mode==='Release / acquire'),value=visible?42:0;
  return `<div class="cs-handoff"><div><h3>Writer</h3><div class="${s.phase>=1?'complete':''}">1. payload ← 42</div><div class="${ready?'complete':''}">2. ready ← true</div></div><span class="cs-handoff-arrow">${s.mode==='Release / acquire'?'release → acquire':'no ordering edge'}</span><div><h3>Reader</h3><div class="${ready?'complete':''}">ready = ${ready?'true':'false'}</div><div class="${ready&&value===42?'complete':''}">payload = ${ready?value:'not read yet'}</div></div></div>`+note(!ready?'Advance both writer steps. The reader checks ready before consuming the payload.':value===0?'The reader sees ready but can still see the old atomic payload in this allowed relaxed execution.':'The payload is visible. A matching release/acquire handoff guarantees this result; relaxed ordering alone does not.',ready&&value===0);
},foot:'Both locations are atomic in the relaxed example. Acquire reads the release’s ready value. Shows permitted visibility, not timed cache propagation.'});

labs.lifetime=()=>({title:'Who still owns the child?',state:{structured:true,cooperative:true,timeout:false,ticks:0,done:false,cancelled:false},controls:[T('structured','Parent owns and joins child'),T('cooperative','Child observes cancellation'),B('tick','Advance child work'),B('timeout','Parent times out')],onChange:s=>{s.timeout=false;s.ticks=0;s.done=false;s.cancelled=false;},actions:{timeout:s=>{s.timeout=true;},tick:s=>{if(s.done)return;if(s.timeout&&s.structured&&s.cooperative){s.done=true;s.cancelled=true;}else{s.ticks++;if(s.ticks>=2)s.done=true;}}},render:s=>{
  const pending=s.timeout&&s.structured&&!s.done;
  return flow([['Parent scope',!s.timeout?(s.done?'child joined':'awaiting child'):pending?'waiting for cleanup':'closed'],['Child',s.done?s.cancelled?'cancelled + cleaned':'completed':s.timeout&&s.structured?'cancel requested':'running','blue'],['Connection',s.done?'released':'held','purple']])+stats(['Work steps completed',s.ticks],['External write',s.ticks?'already sent':'not sent'],['Unowned running child',s.timeout&&!s.structured&&!s.done?'Yes':'No'])+note(pending?'Cancellation has been requested; the scope still waits for the child to stop or finish. Advance the child to observe what it does.':s.timeout&&!s.structured&&!s.done?'The parent is gone while work still holds a connection. Someone must track its result and clean up.':'Try one work step, then time out. Cleanup releases the connection, but it does not undo a write that was already sent.',s.timeout&&!s.structured&&!s.done);
},foot:'Two cooperative work steps, first sends an external write and second completes. A child ignoring cancellation may still finish normally; no external effect is rolled back.'});

labs.batching=()=>({title:'Amortize syscall cost',state:{batch:16,rate:1000},controls:[C('batch','Records per batch',['1','4','16','64','256']),R('rate','Incoming records / second',100,10000,100)],render:s=>{
  const r=batchCost(+s.batch,s.rate);
  return flow([['1,024 records',`${s.batch} per batch`],['Kernel crossings',`${r.calls} calls`,'purple'],['Same payload','1,024 records copied','blue']])+strip([['Syscall overhead μs',r.overhead,colors[0]],['Copy cost μs',r.copying,colors[1]]])+stats(['Modeled work cost',`${fmt(r.total)} μs`],['First record waits to fill',`${fmt(r.fill)} ms`],['Calls avoided',1024-r.calls])+note('Batch fill delay is separate from execution cost. Try a large batch with sparse arrivals; a timer is needed to bound waiting.');
},foot:'1,024 records; 2 μs/call and 0.02 μs/record copied. Deterministic arrivals, full batches, no flush timer or downstream queue.'});

labs.durability=()=>({title:'Cut power between write milestones',state:{stage:0,failed:false},controls:[B('step','Advance one milestone'),B('crash','Cut machine power')],actions:{step:s=>{if(!s.failed)s.stage=Math.min(3,s.stage+1);},crash:s=>{s.failed=true;}},render:s=>{
  const stages=['Application buffer','Kernel page cache','Device volatile cache','Successful fsync'];
  return `<div class="cs-milestones">${stages.map((label,i)=>`<div class="${i<=s.stage?'complete':''} ${s.failed&&i<3?'lost':''}"><small>0${i+1}</small><strong>${label}</strong><span>${i>s.stage?'not reached':s.failed?(i===3?'durable':'volatile state lost'):'reached'}</span></div>`).join('')}</div>`+stats(['write() has returned',s.stage>=1?'Yes':'No'],['Sync completed',s.stage===3?'Yes':'No'],['Power-loss survival',s.failed?s.stage===3?'New data survives':'Not guaranteed':'Not tested'])+note(s.failed?(s.stage===3?'The file data survives under this model’s sync/device assumptions. Reset to compare an earlier crash.':'No durable completion was established. This toy crash loses the unsynced update; a real unsynced write may or may not survive.'):'Advance, then cut power. Once crashed, reset to run a fresh sequence.',s.failed&&s.stage<3);
},foot:'Existing file, successful write/sync, no namespace change. Device honors flushes; stages are conceptual and may overlap on real systems.'});

labs['event-loop']=()=>({title:'Keep the loop available',state:{blocking:true,cpu:2},controls:[T('blocking','A uses blocking I/O'),R('cpu','A CPU phase (ms)',1,100)],render:s=>{
  const r=eventLoop(s.blocking,s.cpu),max=Math.max(r.aEnd,r.bEnd);
  return timeline([['A · CPU',0,s.cpu,colors[0]],['A · I/O wait',s.cpu,40,colors[2]],['B · CPU',r.bStart,2,colors[1]]],max)+stats(['B arrives','5 ms'],['B begins',`${r.bStart} ms`],['B response latency',`${r.bLatency} ms`])+note(s.blocking?'The loop thread is blocked during A’s I/O. B cannot run until A unblocks.':s.cpu>5?'Async I/O frees the loop during the wait, but A’s long CPU phase still delays B.':'A yields while waiting, so B can use the loop immediately on arrival.');
},foot:'Single cooperative event-loop thread. A has one CPU phase then 40 ms I/O; B arrives at 5 ms and needs 2 ms CPU. Completion callbacks cost zero.'});

labs.network=()=>({title:'Fill the pipe',state:{window:64,rtt:50,link:100},controls:[R('window','Effective window (KiB)',16,1024,16),R('rtt','Round-trip time (ms)',5,200,5),R('link','Link capacity (Mb/s)',10,1000,10)],render:s=>{
  const r=tcpThroughput(s.window,s.rtt,s.link),fill=r.throughput/s.link;
  return `<div class="cs-pipe" role="img" aria-label="${fmt(fill*100)} percent of link capacity used"><div style="width:${fill*100}%"></div><span>${fmt(fill*100)}% of link capacity</span></div>`+flow([['Sender',`${s.window} KiB in flight`],['Round trip',`${s.rtt} ms`,'purple'],['Receiver','ACK → next window','blue']])+stats(['Steady ceiling',`${fmt(r.throughput,2)} Mb/s`],['Window / RTT ceiling',`${fmt(r.windowMbps,2)} Mb/s`],['Window to fill link',`${fmt(r.bdpKiB)} KiB`])+note(fill<1?'The effective window is too small to fill this path. More nominal link bandwidth alone leaves the ceiling unchanged.':'The window permits enough in-flight data for the link rate. Other bottlenecks are excluded from this model.');
},foot:'Lossless steady-state upper bound; effective window = min(congestion window, receiver window). No startup, headers, TLS, or application stalls.'});

labs.profiles=()=>({title:'Switch the lens on one request',state:{view:'CPU samples',speed:1},controls:[C('view','Measurement lens',['CPU samples','Elapsed time']),R('speed','Speed up parsing',1,10)],render:s=>{
  const parsing=10/s.speed,cpu=parsing+10,total=cpu+80;
  const flame=`<div class="cs-flame" role="img" aria-label="CPU stack weights: parse ${fmt(parsing)} ms, encode 6 ms, dispatch 4 ms; request total CPU ${fmt(cpu)} ms"><div class="cs-flame-row"><span title="parse: ${fmt(parsing)} ms CPU" style="width:${parsing/cpu*100}%;background:${colors[0]}">parse</span><span title="encode: 6 ms CPU" style="width:${6/cpu*100}%;background:${colors[1]}">encode</span><span title="dispatch: 4 ms CPU" style="width:${4/cpu*100}%;background:${colors[2]}">dispatch</span></div><div class="cs-flame-root">handleRequest · ${fmt(cpu)} ms CPU</div></div><p class="small">Width = sampled CPU weight · vertical position = call depth · horizontal order ≠ time</p>`;
  return (s.view==='CPU samples'?flame+legend([[`parse ${fmt(parsing)} ms`,colors[0]],['encode 6 ms',colors[1]],['dispatch 4 ms',colors[2]]]):strip([['Parse ms',parsing,colors[0]],['Other CPU ms',10,colors[1]],['Waiting ms',80,colors[2]]],'Elapsed request time'))+stats(['CPU time',`${fmt(cpu)} ms`],['End-to-end time',`${fmt(total)} ms`],['End-to-end speedup',`${fmt(100/total,2)}×`])+note('At baseline, parsing is half of CPU time but only a tenth of the request. Speed it up, then switch lenses to see the remaining limit.');
},foot:'Synthetic sequential request: 10 ms parsing + 10 ms other CPU + 80 ms waiting. Exact sample weights, no sampling noise or overlapping spans.'});

labs.tails=()=>({title:'Find the slow minority',state:{slow:1,latency:1000},controls:[R('slow','Slow requests out of 100',0,20),R('latency','Slow-request latency (ms)',100,2000,100)],render:s=>{
  const values=latencySample(s.slow,s.latency),mean=values.reduce((a,b)=>a+b,0)/100;
  return `<div class="cs-dots" role="img" aria-label="${100-s.slow} requests at 10 ms, ${s.slow} at ${s.latency} ms">${values.map((v,i)=>`<span class="${v>10?'slow':''}" title="Request ${i+1}: ${v} ms">${i< s.slow?'!':'·'}</span>`).join('')}</div>`+legend([['10 ms',colors[1]],[`${s.latency} ms`,colors[0]]])+bars([['Mean ms',mean],['p50 ms',percentile(values,.5),colors[1]],['p99 ms',percentile(values,.99),colors[2]],['p100 ms',percentile(values,1),colors[0]]])+note('Try one slow request, then two. The p99 changes abruptly because its rank is fixed while the count of slow observations crosses that rank.');
},foot:'100 completed requests, nearest-rank percentiles, sorted conceptually for quantiles. Timeouts and incomplete requests are not modeled.'});

labs.benchmarks=()=>({title:'Expose a misleading benchmark',state:{order:'Grouped',warm:false,consume:true},controls:[C('order','Trial order',['Grouped','Interleaved']),T('warm','Warm up before measuring'),T('consume','Use the computed result')],render:s=>{
  const runs=benchmark(s.order,s.warm,s.consume),a=runs.filter(x=>x.version==='A').map(x=>x.ms),b=runs.filter(x=>x.version==='B').map(x=>x.ms),mean=xs=>xs.reduce((n,x)=>n+x,0)/xs.length;
  return `<div class="cs-trials" role="img" aria-label="${runs.map((r,i)=>`Trial ${i+1}, ${r.version}, ${r.ms} ms`).join('; ')}">${runs.map((r,i)=>`<div><b>${fmt(r.ms)}</b><div><i style="height:${r.ms/25*100}%;background:${r.version==='A'?colors[0]:colors[1]}"></i></div><span>${i+1} · ${r.version}</span></div>`).join('')}</div>`+stats(['Measured A mean',`${fmt(mean(a))} ms`],['Measured B mean',`${fmt(mean(b))} ms`],['Underlying work A / B',s.consume?'10 / 8 ms':'Removed'])+note(!s.consume?'The numbers are tiny because the modeled optimizer removed the useful work. This result does not compare the implementations.':'The toy adds 12 ms to the first two cold trials and 0.5 ms drift per trial. Warm up and interleave to reduce bias; repeat and randomize in real measurements.',!s.consume);
},foot:'Deterministic synthetic trials, not browser timing. Underlying A=10 ms, B=8 ms. No random noise; interleaving reduces but does not eliminate drift bias.'});

const incidents={
  'CPU quota':{metrics:[['Host CPU','18%'],['Container throttled periods','72%'],['Runnable queue','8 threads'],['Storage latency','normal']],right:'Inspect quota and runnable delay',evidence:'The cgroup allows one CPU-equivalent despite eight visible CPUs. In a controlled run with two CPU-equivalents, throttling and latency fall.',next:'Compare the same offered load, cost, queueing, and p99 before changing the production quota.'},
  'Lock contention':{metrics:[['Host CPU','22%'],['Lock wait share','68% of elapsed time'],['Critical-section work','one shared map'],['Network RTT','normal']],right:'Inspect lock holders and waiters',evidence:'An off-CPU trace finds requests waiting behind a lock held across file I/O. CPU optimization does not remove that wait.',next:'Test moving I/O outside the critical section while preserving the map’s invariant.'},
  'Memory pressure':{metrics:[['CPU busy','35%'],['Major faults / second','rising'],['Resident working set','above available memory'],['Storage reads','rising with stalls']],right:'Inspect working set and paging',evidence:'Fault traces and memory pressure align with the latency spikes. A smaller retained working set reduces both faults and storage traffic.',next:'Compare object retention and access locality; test a bounded working set or a justified capacity change.'},
  'One hot core':{metrics:[['Host CPU · 8 cores','13%'],['Busiest core','100%'],['Loop delay','120 ms'],['Longest callback','118 ms parsing']],right:'Profile the busy thread',evidence:'A per-thread CPU profile identifies parsing inside the event-loop callback. Seven mostly idle cores cannot preempt this callback.',next:'Test smaller compute slices or a bounded worker pool, including serialization, transfer cost, and correctness.'}
};
const hypotheses=['Inspect quota and runnable delay','Inspect lock holders and waiters','Inspect working set and paging','Profile the busy thread'];
labs.diagnosis=()=>({title:'Choose the next measurement',state:{incident:'CPU quota',hypothesis:hypotheses[0],revealed:false},controls:[C('incident','Incident',Object.keys(incidents)),C('hypothesis','Next measurement',hypotheses),B('reveal','Test the hypothesis')],onChange:s=>{s.revealed=false;},actions:{reveal:s=>{s.revealed=true;}},render:s=>{
  const incident=incidents[s.incident],match=s.hypothesis===incident.right;
  return table(['Observed signal','Evidence'],incident.metrics)+`<div class="cs-diagnostic">${flow([['Observe',s.incident],['Hypothesis',s.hypothesis,'blue'],['Validate',s.revealed?match?'supported':'reconsider':'not tested','purple']])}</div>`+note(s.revealed?match?`${incident.evidence} Next: ${incident.next}`:`That measurement may be useful later, but it misses the strongest signals here. Try: ${incident.right.toLowerCase()}.`:'Read the evidence, select the measurement that can test a cause, then reveal the result.',s.revealed&&!match);
},foot:'Four curated incidents with synthetic observations. Evidence narrows hypotheses; these are not universal diagnoses from individual metrics.'});

export const mountLab=(element,id)=>mountExperiment(element,labs[id]());
export const labIds=()=>Object.keys(labs);
export const createLab=id=>labs[id]();
